cl /nologo /W3 /MD poc.c /I ..\include /link /LIBPATH:..\build libuv.lib
advapi32.lib iphlpapi.lib psapi.lib shell32.lib user32.lib userenv.lib
ws2_32.lib dbghelp.lib ole32.lib uuid.lib
poc.exe
```

