 {
    size_t x=0;
@@ -430,16 +436,14 @@ size_t iconv(iconv_t cd, char **restrict in, size_t *restrict inb, char **restri
                d = *((unsigned char *)*in + 3);
                if (d-'0'>9) goto ilseq;
