	sec = adj(0x48b, SEC_EPT);
	exitc = adj(0x483, EXIT_HOST_ADDR | EXIT_LOAD_EFER);
	entryc = adj(0x484, ENTRY_IA32E | ENTRY_LOAD_EFER);
	if (!(proc & CPU_SEC_CTLS) || !(sec & SEC_EPT)) {
		pr_err("poc: NO EPT ctl cpu%d\n", cpu);
