}

static void emit_touch_loop(uint8_t **lp, int cnt)
{
	uint8_t *l = *lp;

	if (cnt <= 0)
		return;
	*l++ = 0xb9;
	*(uint32_t *)l = (uint32_t)cnt;
	l += 4;
	*l++ = 0x8b;
	*l++ = 0x03;
	*l++ = 0x81;
	*l++ = 0xc3;
	*(uint32_t *)l = 0x200000;
	l += 4;
	*l++ = 0x49;
	*l++ = 0x75;
	*l++ = 0xf5;
	*lp = l;
}

static void emit_l2_phase_a(void)
{
	uint8_t *l = M + L2_CODE;
	*l++ = 0xb9;
	*(uint32_t *)l = (uint32_t)QA;
	l += 4;
	*l++ = 0x89;
	*l++ = 0x0d;
	*(uint32_t *)l = 0x1004;
	l += 4;
	*l++ = 0xa1;
	*(uint32_t *)l = 0x1000;
	l += 4;
	*l++ = 0xbb;
	*(uint32_t *)l = 0x00200000u;
	l += 4;
	emit_touch_loop(&l, 56);
	*l++ = 0xbb;
	*(uint32_t *)l = 0x40000000u;
	l += 4;
	emit_touch_loop(&l, 512);
	*l++ = 0xbb;
	*(uint32_t *)l = 0x80000000u;
	l += 4;
	emit_touch_loop(&l, 512);
	*l++ = 0xbb;
	*(uint32_t *)l = 0xc0000000u;
	l += 4;
	emit_touch_loop(&l, 511);
	*l++ = 0x89;
	*l++ = 0x1d;
	*(uint32_t *)l = 0x1008;
	l += 4;
	*l++ = 0xc6;
	*l++ = 0x05;
	*(uint32_t *)l = 0x1803;
	l += 4;
	*l++ = 'A';
	uint8_t *wait = l;
	*l++ = 0x80;
	*l++ = 0x3d;
	*(uint32_t *)l = 0x1802;
	l += 4;
	*l++ = 'R';
	*l++ = 0x74;
	*l++ = 0x04;
	*l++ = 0xf3;
	*l++ = 0x90;
	int8_t back = (int8_t)(wait - (l + 2));
	*l++ = 0xeb;
	*l++ = (uint8_t)back;
	*l++ = 0x0f;
	*l++ = 0x01;
	*l++ = 0xd9;
	*l++ = 0xf4;
}

static void emit_l2_phase_b(void)
{
	uint8_t *l = M + L2_CODE + 0x400;
	*l++ = 0xb9;
	*(uint32_t *)l = (uint32_t)QB;
	l += 4;
	*l++ = 0x89;
	*l++ = 0x0d;
	*(uint32_t *)l = 0x1004;
	l += 4;
	*l++ = 0xa1;
	*(uint32_t *)l = 0x1000;
	l += 4;
	*l++ = 0xbb;
	*(uint32_t *)l = 0x200000;
	l += 4;
	emit_touch_loop(&l, 57);
	*l++ = 0x8b;
	*l++ = 0x03;
	*l++ = 0xc6;
	*l++ = 0x05;
	*(uint32_t *)l = 0x1800;
	l += 4;
	*l++ = 'C';
	uint8_t *wait_clear = l;
	*l++ = 0x80;
	*l++ = 0x3d;
	*(uint32_t *)l = 0x1801;
	l += 4;
	*l++ = 'D';
	*l++ = 0x74;
	*l++ = 0x04;
	*l++ = 0xf3;
	*l++ = 0x90;
	int8_t wait_clear_back = (int8_t)(wait_clear - (l + 2));
	*l++ = 0xeb;
	*l++ = (uint8_t)wait_clear_back;
	*l++ = 0x89;
	*l++ = 0x1d;
	*(uint32_t *)l = 0x1008;
	l += 4;
	*l++ = 0xc6;
	*l++ = 0x05;
	*(uint32_t *)l = 0x1804;
	l += 4;
	*l++ = 'T';
	*l++ = 0x0f;
	*l++ = 0x01;
	*l++ = 0xd9;
	*l++ = 0xf4;
}

static void build_l2(void)
{
	emit_l2_phase_a();
	emit_l2_phase_b();
	*(uint32_t *)(M + L2_DATA) = 0xdeadbeef;
	*(uint32_t *)(M + L2_QUOTA_BK) = 0x11111111;
}

