static void emit64_store8_abs(uint8_t **pp, uint32_t addr, uint8_t value)
{
	uint8_t *p = *pp;

	e8(&p, 0xc6);
	e8(&p, 0x04);
	e8(&p, 0x25);
	e32(&p, addr);
	e8(&p, value);
	*pp = p;
}

