	e8(&p, 0xc7);
	e8(&p, 0x0e);
	e8(&p, 0x81);
	e8(&p, 0xfa);
	e32(&p, KASLR_ARENA_HI_MIN);
	below_direct_map[1] = emit_rel32_jcc(&p, 0x82);
	e8(&p, 0x81);
	e8(&p, 0xfa);
	e32(&p, KASLR_ARENA_HI_END);
	past_direct_map[1] = emit_rel32_jcc(&p, 0x83);
	e8(&p, 0xa9);
	e32(&p, 7);
	not_aligned = emit_rel32_jcc(&p, 0x85);
	e8(&p, 0x25);
	e32(&p, 0xfffu);
