	e8(&p, 0x83);
	e8(&p, 0xf8);
	e8(&p, MMU_HEADERS_PER_SLAB - 1u);
	bad_pointee_slot = emit_rel32_jcc(&p, 0x87);
	e8(&p, 0x89);
	e8(&p, 0xf0);
	e8(&p, 0x83);
	e8(&p, 0xe8);
	e8(&p, 0x08);
	e8(&p, 0x25);
	e32(&p, 0xfffu);
	e8(&p, 0x31);
	e8(&p, 0xd2);
	e8(&p, 0xf7);
