	e8(&p, 0x85);
	e8(&p, 0xc9);
	c_done = emit_rel32_jcc(&p, 0x84);
	c_more = p;
	e8(&p, 0x8b);
	e8(&p, 0x16);
	e8(&p, 0x01);
	e8(&p, 0x02);
	e8(&p, 0x83);
	e8(&p, 0xc6);
	e8(&p, 0x04);
	e8(&p, 0x49);
	{
		uint8_t *d = emit_rel32_jcc(&p, 0x85);

		patch_rel32(d, c_more);
